    addRail([-0.84, 0.24, 0.18], [0.12, 0.08, 0.02]);
    addRail([-0.68, 0.72, -0.12], [0.08, 0.12, -0.02]);
    addRail([0.74, -0.14, -0.26], [0.02, 0.1, 0.0]);
    addRail([0.54, 0.58, 0.36], [-0.04, 0.18, 0.04]);
