    for (let i = 0; i < corePos.count; i++) {
      const x = corePos.getX(i);
      const y = corePos.getY(i);
      const z = corePos.getZ(i);
      const yNorm = (y + 0.43) / 0.86;
      const taper = 0.82 + yNorm * 0.36;
      corePos.setXYZ(
        i,
        x * taper + z * 0.06,
        y * 1.08,
        z * (0.74 + yNorm * 0.18) - x * 0.08
      );
    }
    corePos.needsUpdate = true;
