      group.userData.relayCorePulseSpeed = 0.54 + rng() * 0.08;
      group.userData.relayCorePulseAmplitude = 0.012 + rng() * 0.004;
      group.userData.relayDiademPrecessionSpeed = 0.012 + rng() * 0.004;
