        shell1.frustumCulled = false;
        shell1.renderOrder = EnhancedNodeModels._getArchetypeRenderOrder();
        if (shell1.material?.uniforms?.uOpacity) shell1.material.uniforms.uOpacity.value = 0.06;
        auraGroup.add(shell1);
